∀ {k n d N : ℕ} {cuts : RiffleUpperV2.Cuts k n d} {R : Finset (Fin n)} {chi delta : ℝ}
  (b : RiffleUpperV2.FirstMoment.Blocks N cuts R chi delta),
  ↑(↑b).2.2.fst < d + 1 → ↑(↑b).1.fst = d → ↑(↑b).1.fst ≤ ↑(↑b).2.2.fst → ¬↑(↑b).2.2.fst = d → False

∀ {k n d : ℕ} (cuts : RiffleUpperV2.Cuts k n d) (hn : 0 < n) (chi : ℝ) (j : Fin d),
  RiffleUpperV2.FirstMoment.rareDigits cuts hn chi j =
    {b : Fin k | TimeProfile.prob (TimeProfile.Cuts.profile cuts hn j) b < chi}

∀ {m i : ℕ} (P : Fin m → Prop) [inst : DecidablePred P],
  have S := fun (j : ℕ) => {e : Fin m | ↑e + 1 < j ∧ P e};
  (S (i + 1)).card = (S i).card ∨ (S (i + 1)).card = (S i).card + 1

∀ {k n d : ℕ} {cuts : RiffleUpperV2.Cuts k n d} (R : Finset (Fin n)) (W : Finset (Fin d → Fin k))
  (omega : RiffleUpperV2.Sample cuts),
  RiffleUpperV2.FirstMoment.rowsInWords R W omega = {r ∈ R | TimeProfile.sampleRow omega r ∈ W}

∀ {k n d : ℕ} {cuts : RiffleUpperV2.Cuts k n d} {c₀ : ℤ} {R : Finset (Fin n)} {x : RiffleUpperV2.Prefix k d} {g w D : ℝ}
  (self : RiffleUpperV2.Anchor.EndpointSmoothingData cuts c₀ R x g w D) (ω : RiffleUpperV2.Sample cuts),
  self.good ω → g * w / (16 * D) ≤ (self.params ω).varianceFormula

∀ {k d : ℕ} (x : RiffleUpperV2.Prefix k d) (i j : Fin ↑x.fst) (D : Finset (Fin k)),
  ↑j < ↑i →
    RiffleUpperV2.Anchor.prefixThenDigits x i D (RiffleUpperV2.Anchor.prefixColumn x j) = {List.Vector.get x.snd j}

∀ {k n d : ℕ} {cuts : RiffleUpperV2.Cuts k n d} (R : Finset (Fin n)) (w : RiffleUpperV2.Word k d)
  (ω : RiffleUpperV2.Sample cuts),
  RiffleUpperV2.Anchor.prefixRows R (RiffleLowerV2.fullPrefix w) ω = {r ∈ R | RiffleUpperV2.rowWord ω r = w}

∀ {J : Type u_1} [inst : Fintype J] [inst_1 : DecidableEq J] {k : ℕ} (p : J → TimeProfile.Simplex k) (I : Finset J)
  (chi : ℝ) (w : J → Fin k),
  RiffleUpperV2.FirstMoment.exceptionalPositions p I chi w = {j ∈ I | TimeProfile.prob (p j) (w j) < chi}

∀ {k d : ℕ} {v w : RiffleUpperV2.Prefix k d} {Q : RiffleUpperV2.Prefix k d → Prop}
  (hex : ∃ (m : ℕ) (hm : m ≤ ↑w.fst), ↑v.fst ≤ m ∧ (Q (RiffleUpperV2.Localization.takePrefix w m hm) ∨ m = d))
  (u : RiffleUpperV2.Prefix k d), Nat.find hex ≤ ↑u.fst → ↑u.fst < Nat.find hex → False

∀ {k n d : ℕ} {cuts : RiffleUpperV2.Cuts k n d} (s : RiffleUpperV2.Anchor.SuffixSide) (R : Finset (Fin n))
  (x : RiffleUpperV2.Prefix k d) (j : Fin ↑x.fst) (ω : RiffleUpperV2.Sample cuts),
  have P := RiffleUpperV2.Anchor.unequalEndpointParams s R x j ω;
  have A := RiffleUpperV2.Anchor.unequalExposedRows s R x j ω;
  have D := s.allowed (List.Vector.get x.snd j);
  P.population = n - A.card ∧
    P.marked = (RiffleUpperV2.Anchor.residualAllowed A D (ω (RiffleUpperV2.Anchor.prefixColumn x j))).card ∧
      P.draws = (RiffleUpperV2.Anchor.unequalSampleRows s R x j ω).card ∧
        P.population - P.marked =
          (RiffleUpperV2.Anchor.residualAllowed A (Finset.univ \ D) (ω (RiffleUpperV2.Anchor.prefixColumn x j))).card

∀ {k n : ℕ} {count : ℕ → Fin k → ℕ} {sum_count : ∀ (j : ℕ), ∑ d : Fin k, count j d = n} {count_1 : ℕ → Fin k → ℕ}
  {sum_count_1 : ∀ (j : ℕ), ∑ d : Fin k, count_1 j d = n},
  { count := count, sum_count := sum_count } = { count := count_1, sum_count := sum_count_1 } → count = count_1

∀ {k n L : ℕ} (cuts : RiffleUpperV2.Cuts k n (L + 1)) (D : ℕ) {g ξ : ℝ} {ω ω' : RiffleUpperV2.Sample cuts}
  ⦃e : Fin (n - 1)⦄ (p : Fin k) (t : Fin (RiffleUpperV2.Exploration.pileSize cuts p - 1)),
  ¬↑t < RiffleUpperV2.Exploration.pileSize cuts p → False

∀ (p : RiffleLowerV2.Thinning.Compat.HypergeomParams),
  RiffleUpperV2.Anchor.swappedParams p =
    { population := p.population, marked := p.draws, draws := p.marked, marked_le := ⋯, draws_le := ⋯ }

∀ {k n d : ℕ} {cuts : RiffleUpperV2.Cuts k n d} {j : Fin d} (A : Finset (Fin n)) (D : Finset (Fin k))
  (c : TimeProfile.ColumnAssignments cuts j),
  RiffleUpperV2.Anchor.residualAllowed A D c = {r ∈ Finset.univ \ A | ↑c r ∈ D}

∀ {k n d : ℕ} {cuts : RiffleUpperV2.Cuts k n d} {c₀ : ℤ} {R : Finset (Fin n)} {x : RiffleUpperV2.Prefix k d}
  {History : Type} {finiteHistory : Fintype History} {history : RiffleUpperV2.Sample cuts → History}
  {good : RiffleUpperV2.Sample cuts → Prop}
  {params : RiffleUpperV2.Sample cuts → RiffleLowerV2.Thinning.Compat.HypergeomParams}
  {shift : RiffleUpperV2.Sample cuts → ℤ}
  {refines : RiffleUpperV2.Anchor.Refines history (RiffleUpperV2.Anchor.internalHistory R x)}
  {good_measurable : ∀ (ω₀ ω : RiffleUpperV2.Sample cuts), history ω = history ω₀ → (good ω ↔ good ω₀)}
  {shift_measurable : ∀ (ω₀ ω : RiffleUpperV2.Sample cuts), history ω = history ω₀ → shift ω = shift ω₀}
  {endpoint_law :
    ∀ (ω₀ : RiffleUpperV2.Sample cuts) (f : ℤ → ℝ),
      ((RiffleUpperV2.conditionalExpect (RiffleUpperV2.fixedCountPMF cuts)
            (fun (ω : TimeProfile.ShuffleSample cuts) => f (RiffleUpperV2.Anchor.lowerEndpoint c₀ R x ω))
            fun (ω : TimeProfile.ShuffleSample cuts) => history ω = history ω₀) =
          RiffleUpperV2.expect (params ω₀).law.toPMF fun (q : Fin ((params ω₀).draws + 1)) => f (shift ω₀ + ↑↑q)) ∧
        (RiffleUpperV2.conditionalExpect (RiffleUpperV2.fixedCountPMF cuts)
            (fun (ω : TimeProfile.ShuffleSample cuts) => f (RiffleUpperV2.Anchor.upperEndpoint c₀ R x ω))
            fun (ω : TimeProfile.ShuffleSample cuts) => history ω = history ω₀) =
          RiffleUpperV2.expect (params ω₀).law.toPMF fun (q : Fin ((params ω₀).draws + 1)) =>
            f (shift ω₀ + ↑↑q + ↑(RiffleUpperV2.Anchor.prefixRows R x ω₀).card)}
  {History_1 : Type} {finiteHistory_1 : Fintype History_1} {history_1 : RiffleUpperV2.Sample cuts → History_1}
  {good_1 : RiffleUpperV2.Sample cuts → Prop}
  {params_1 : RiffleUpperV2.Sample cuts → RiffleLowerV2.Thinning.Compat.HypergeomParams}
  {shift_1 : RiffleUpperV2.Sample cuts → ℤ}
  {refines_1 : RiffleUpperV2.Anchor.Refines history_1 (RiffleUpperV2.Anchor.internalHistory R x)}
  {good_measurable_1 : ∀ (ω₀ ω : RiffleUpperV2.Sample cuts), history_1 ω = history_1 ω₀ → (good_1 ω ↔ good_1 ω₀)}
  {shift_measurable_1 : ∀ (ω₀ ω : RiffleUpperV2.Sample cuts), history_1 ω = history_1 ω₀ → shift_1 ω = shift_1 ω₀}
  {endpoint_law_1 :
    ∀ (ω₀ : RiffleUpperV2.Sample cuts) (f : ℤ → ℝ),
      ((RiffleUpperV2.conditionalExpect (RiffleUpperV2.fixedCountPMF cuts)
            (fun (ω : TimeProfile.ShuffleSample cuts) => f (RiffleUpperV2.Anchor.lowerEndpoint c₀ R x ω))
            fun (ω : TimeProfile.ShuffleSample cuts) => history_1 ω = history_1 ω₀) =
          RiffleUpperV2.expect (params_1 ω₀).law.toPMF fun (q : Fin ((params_1 ω₀).draws + 1)) =>
            f (shift_1 ω₀ + ↑↑q)) ∧
        (RiffleUpperV2.conditionalExpect (RiffleUpperV2.fixedCountPMF cuts)
            (fun (ω : TimeProfile.ShuffleSample cuts) => f (RiffleUpperV2.Anchor.upperEndpoint c₀ R x ω))
            fun (ω : TimeProfile.ShuffleSample cuts) => history_1 ω = history_1 ω₀) =
          RiffleUpperV2.expect (params_1 ω₀).law.toPMF fun (q : Fin ((params_1 ω₀).draws + 1)) =>
            f (shift_1 ω₀ + ↑↑q + ↑(RiffleUpperV2.Anchor.prefixRows R x ω₀).card)},
  { History := History, finiteHistory := finiteHistory, history := history, good := good, params := params,
        shift := shift, refines := refines, good_measurable := good_measurable, shift_measurable := shift_measurable,
        endpoint_law := endpoint_law } =
      { History := History_1, finiteHistory := finiteHistory_1, history := history_1, good := good_1,
        params := params_1, shift := shift_1, refines := refines_1, good_measurable := good_measurable_1,
        shift_measurable := shift_measurable_1, endpoint_law := endpoint_law_1 } →
    History = History_1 ∧
      finiteHistory ≍ finiteHistory_1 ∧ history ≍ history_1 ∧ good = good_1 ∧ params = params_1 ∧ shift = shift_1

∀ {k n d : ℕ} {cuts : RiffleUpperV2.Cuts k n d} {c₀ : ℤ} {R : Finset (Fin n)} {x : RiffleUpperV2.Prefix k d} {g w D : ℝ}
  {toEndpointReveal : RiffleUpperV2.Anchor.EndpointReveal cuts c₀ R x}
  {failure :
    (RiffleUpperV2.probability (RiffleUpperV2.fixedCountPMF cuts) fun (ω : TimeProfile.ShuffleSample cuts) =>
        ¬toEndpointReveal.good ω) ≤
      3 * Real.exp (-RiffleLowerV2.chernoffConstant * g * w)}
  {variance :
    ∀ (ω : RiffleUpperV2.Sample cuts),
      toEndpointReveal.good ω → g * w / (16 * D) ≤ (toEndpointReveal.params ω).varianceFormula}
  {toEndpointReveal_1 : RiffleUpperV2.Anchor.EndpointReveal cuts c₀ R x}
  {failure_1 :
    (RiffleUpperV2.probability (RiffleUpperV2.fixedCountPMF cuts) fun (ω : TimeProfile.ShuffleSample cuts) =>
        ¬toEndpointReveal_1.good ω) ≤
      3 * Real.exp (-RiffleLowerV2.chernoffConstant * g * w)}
  {variance_1 :
    ∀ (ω : RiffleUpperV2.Sample cuts),
      toEndpointReveal_1.good ω → g * w / (16 * D) ≤ (toEndpointReveal_1.params ω).varianceFormula},
  { toEndpointReveal := toEndpointReveal, failure := failure, variance := variance } =
      { toEndpointReveal := toEndpointReveal_1, failure := failure_1, variance := variance_1 } →
    toEndpointReveal = toEndpointReveal_1

∀ {k n d : ℕ} {cuts : RiffleUpperV2.Cuts k n d} {c₀ : ℤ} {R : Finset (Fin n)} {x : RiffleUpperV2.Prefix k d}
  (self : RiffleUpperV2.Anchor.EndpointReveal cuts c₀ R x),
  RiffleUpperV2.Anchor.Refines self.history (RiffleUpperV2.Anchor.internalHistory R x)

∀ {k n d : ℕ} {cuts : RiffleUpperV2.Cuts k n d} {c₀ : ℤ} {R : Finset (Fin n)} {x : RiffleUpperV2.Prefix k d}
  (self : RiffleUpperV2.Anchor.EndpointReveal cuts c₀ R x) (ω₀ ω : RiffleUpperV2.Sample cuts),
  self.history ω = self.history ω₀ → (self.good ω ↔ self.good ω₀)

∀ {k n d N : ℕ} {cuts : RiffleUpperV2.Cuts k n d} {R : Finset (Fin n)} {chi delta : ℝ}
  (b : RiffleUpperV2.FirstMoment.Blocks N cuts R chi delta),
  RiffleUpperV2.Localization.TerminalBoundaryPair (↑b).1 (↑b).2.1 → ↑(↑b).2.2.fst = d

∀ {k n d : ℕ} (u : RiffleUpperV2.Anchor.InternalHistory k n d) (w : Fin d → Fin k),
  RiffleUpperV2.Localization.historyLessRows u w =
    {r : Fin n | ∃ (q : Fin d → Fin k), u r = some q ∧ List.ofFn q < List.ofFn w}

∀ {k n d N : ℕ} {cuts : RiffleUpperV2.Cuts k n d} {R : Finset (Fin n)} {chi delta : ℝ}
  (b : RiffleUpperV2.FirstMoment.Blocks N cuts R chi delta),
  ↑(↑b).2.2.fst < d + 1 → ↑(↑b).2.1.fst = d → ↑(↑b).2.1.fst ≤ ↑(↑b).2.2.fst → ¬↑(↑b).2.2.fst = d → False

∀ {k n d : ℕ} {cuts : RiffleUpperV2.Cuts k n d} (R : Finset (Fin n)) (W : Finset (RiffleUpperV2.Word k d))
  (ω : RiffleUpperV2.Sample cuts),
  RiffleUpperV2.Localization.rowsInWords R W ω = {r ∈ R | RiffleUpperV2.rowWord ω r ∈ W}

∀ {k n d : ℕ} {cuts : RiffleUpperV2.Cuts k n d} (R : Finset (Fin n)) (w : Fin d → Fin k)
  (omega : RiffleUpperV2.Sample cuts),
  RiffleUpperV2.FirstMoment.wordRows R w omega = {r ∈ R | TimeProfile.sampleRow omega r = w}

∀ {k n d : ℕ} {cuts : RiffleUpperV2.Cuts k n d} {c₀ : ℤ} {R : Finset (Fin n)} {x : RiffleUpperV2.Prefix k d}
  (self : RiffleUpperV2.Anchor.EndpointReveal cuts c₀ R x) (ω₀ ω : RiffleUpperV2.Sample cuts),
  self.history ω = self.history ω₀ → self.shift ω = self.shift ω₀

∀ {α : Type u_1} (V A : Finset α) (m : ℕ) (hA : A ⊆ V) (hm : m ≤ V.card),
  RiffleLowerV2.Thinning.Compat.samplingParams V A m hA hm =
    { population := V.card, marked := A.card, draws := m, marked_le := ⋯, draws_le := hm }

∀ {k n d N : ℕ} {cuts : RiffleUpperV2.Cuts k n d} {R : Finset (Fin n)} {v : RiffleUpperV2.Prefix k d} {δ : ℝ}
  {x : RiffleUpperV2.Prefix k d},
  RiffleUpperV2.Localization.ProperStable N cuts R v δ x → ¬RiffleUpperV2.Localization.Stops N cuts R v δ v

∀ {k n L : ℕ} (cuts : RiffleUpperV2.Cuts k n (L + 1)) (D : ℕ) {g ξ : ℝ} {ω ω' : RiffleUpperV2.Sample cuts}
  ⦃e : Fin (n - 1)⦄ (p : Fin k) (t : Fin (RiffleUpperV2.Exploration.pileSize cuts p - 1)),
  ¬↑t + 1 < RiffleUpperV2.Exploration.pileSize cuts p → False

∀ {k n d : ℕ} {cuts : RiffleUpperV2.Cuts k n d} {j : Fin d} (a : Fin k) (c₀ : TimeProfile.ColumnAssignments cuts j),
  RiffleUpperV2.Anchor.residualMarked (RiffleUpperV2.Anchor.equalityRows a c₀) {x : Fin k | x < a} c₀ =
    RiffleUpperV2.Hypergeometric.allowedCount cuts j {x : Fin k | x < a}

∀ {k n d N : ℕ} {cuts : RiffleUpperV2.Cuts k n d} {R : Finset (Fin n)} {chi delta : ℝ}
  (b : RiffleUpperV2.FirstMoment.Blocks N cuts R chi delta) {w : RiffleUpperV2.Prefix k d},
  ↑w.fst < d + 1 → ↑(↑b).2.2.fst = d → ↑(↑b).2.2.fst ≤ ↑w.fst → ¬↑(↑b).2.2.fst = ↑w.fst → False

∀ {k d : ℕ} (default : Fin d → Fin k) (x : RiffleUpperV2.Prefix k d),
  RiffleUpperV2.FirstMoment.boundaryExceptions default x =
    {j : Fin d | ↑j + 1 < ↑x.fst ∧ RiffleUpperV2.FirstMoment.completePrefix default x j ≠ default j}
